import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Language = 'ENG' | 'HIN';

export interface Transaction {
  id: string;
  merchant: string;
  amount: number;
  category: 'Wise' | 'Impulsive';
  date: string;
  icon: string;
  imageUrl?: string;
}

export interface Goal {
  id: string;
  name: string;
  targetAmount: number;
  savedAmount: number;
  targetDate: string;
  icon: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
  insightData?: any;
}

export interface AppState {
  user: {
    name: string;
    avatar: string;
  };
  language: Language;
  monthlyAllowance: number;
  transactions: Transaction[];
  goals: Goal[];
  currentScreen: 'welcome' | 'setup' | 'dashboard' | 'analytics' | 'tools' | 'chat' | 'offers' | 'scan' | 'settings';
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getFinancialAdvice = async (prompt: string, history: any[] = []) => {
  const model = ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      systemInstruction: "You are WiseupAI Financial Guru, a friendly, slightly cheeky, and wise financial advisor for Indian students. Use Hinglish (a mix of Hindi and English) to sound relatable. Your goal is to help students save money for their long-term goals and roast them gently when they spend impulsively.",
      temperature: 0.8,
    }
  });

  const response = await model;
  return response.text;
};

export const getTransactionInsight = async (transaction: any, goals: any[]) => {
  const prompt = `Analyze this transaction: ${JSON.stringify(transaction)}. 
  The user has these goals: ${JSON.stringify(goals)}. 
  Provide a witty insight in Hinglish about how this spending affects their goals. 
  Suggest what they could have bought for their goal instead.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          insight: { type: Type.STRING },
          impactPercentage: { type: Type.NUMBER },
          alternativePurchase: { type: Type.STRING }
        },
        required: ["insight", "impactPercentage", "alternativePurchase"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useCallback } from 'react';
import WelcomeScreen from './screens/WelcomeScreen';
import SetupScreen from './screens/SetupScreen';
import DashboardScreen from './screens/DashboardScreen';
import AnalyticsScreen from './screens/AnalyticsScreen';
import ToolsScreen from './screens/ToolsScreen';
import ChatScreen from './screens/ChatScreen';
import OffersScreen from './screens/OffersScreen';
import SettingsScreen from './screens/SettingsScreen';
import ScanResultScreen from './screens/ScanResultScreen';
import Navigation from './components/Navigation';
import { AppState, Language, Transaction, Goal } from './types';

const INITIAL_GOALS: Goal[] = [
  {
    id: '1',
    name: 'Gaming Laptop',
    targetAmount: 80000,
    savedAmount: 45000,
    targetDate: 'Nov 2024',
    icon: 'laptop_mac'
  },
  {
    id: '2',
    name: 'Sony WH-1000XM5',
    targetAmount: 30000,
    savedAmount: 20000,
    targetDate: 'Dec 2024',
    icon: 'headphones'
  }
];

const INITIAL_TRANSACTIONS: Transaction[] = [
  { id: '1', merchant: 'Starbucks Coffee', amount: 350, category: 'Impulsive', date: 'Oct 21 • 4:30 PM', icon: 'coffee' },
  { id: '2', merchant: 'Udemy Course', amount: 499, category: 'Wise', date: 'Oct 19 • 10:00 AM', icon: 'school' },
  { id: '3', merchant: 'Fresh Mart Grocery', amount: 1200, category: 'Wise', date: 'Oct 18 • 6:15 PM', icon: 'shopping_cart' },
  { id: '4', merchant: 'App Store Games', amount: 850, category: 'Impulsive', date: 'Oct 15 • 9:20 PM', icon: 'videogame_asset' },
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: { name: 'Rahul', avatar: 'https://picsum.photos/100/100' },
    language: 'ENG',
    monthlyAllowance: 0,
    transactions: INITIAL_TRANSACTIONS,
    goals: INITIAL_GOALS,
    currentScreen: 'welcome'
  });

  const updateScreen = (screen: AppState['currentScreen']) => {
    setState(prev => ({ ...prev, currentScreen: screen }));
  };

  const setAllowance = (amount: number) => {
    setState(prev => ({ ...prev, monthlyAllowance: amount, currentScreen: 'dashboard' }));
  };

  const toggleLanguage = () => {
    setState(prev => ({ ...prev, language: prev.language === 'ENG' ? 'HIN' : 'ENG' }));
  };

  const renderScreen = () => {
    switch (state.currentScreen) {
      case 'welcome':
        return <WelcomeScreen onContinue={() => updateScreen('setup')} />;
      case 'setup':
        return <SetupScreen onSave={setAllowance} />;
      case 'dashboard':
        return <DashboardScreen state={state} onAction={(screen) => updateScreen(screen)} />;
      case 'analytics':
        return <AnalyticsScreen state={state} onBack={() => updateScreen('dashboard')} />;
      case 'tools':
        return <ToolsScreen state={state} onBack={() => updateScreen('dashboard')} />;
      case 'chat':
        return <ChatScreen state={state} onBack={() => updateScreen('dashboard')} />;
      case 'offers':
        return <OffersScreen state={state} onBack={() => updateScreen('dashboard')} />;
      case 'scan':
        return <ScanResultScreen state={state} onBack={() => updateScreen('dashboard')} />;
      case 'settings':
        return <SettingsScreen state={state} onBack={() => updateScreen('dashboard')} onLogout={() => updateScreen('welcome')} onToggleLang={toggleLanguage} />;
      default:
        return <DashboardScreen state={state} onAction={(screen) => updateScreen(screen)} />;
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-[#050505]">
      <div className="w-full max-w-md relative flex flex-col bg-background-dark shadow-2xl overflow-hidden min-h-screen">
        {renderScreen()}
        {['dashboard', 'analytics', 'tools', 'chat', 'offers'].includes(state.currentScreen) && (
          <Navigation currentScreen={state.currentScreen} onNavigate={updateScreen} />
        )}
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { AppState } from '../types';

interface NavigationProps {
  currentScreen: AppState['currentScreen'];
  onNavigate: (screen: AppState['currentScreen']) => void;
}

const Navigation: React.FC<NavigationProps> = ({ currentScreen, onNavigate }) => {
  const navItems: { screen: AppState['currentScreen']; label: string; icon: string }[] = [
    { screen: 'dashboard', label: 'Home', icon: 'home' },
    { screen: 'analytics', label: 'Stats', icon: 'analytics' },
    { screen: 'chat', label: 'Guru', icon: 'psychology' },
    { screen: 'offers', label: 'Offers', icon: 'local_offer' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 flex flex-col items-center pointer-events-none">
      <div className="w-full max-w-md pointer-events-auto">
        <div className="relative glass pb-6 pt-2 px-6 flex items-center justify-between border-t border-white/5 bg-[#0a0a0f]/90 backdrop-blur-xl">
          {/* Floating Scan Button */}
          <div className="absolute -top-10 left-1/2 transform -translate-x-1/2">
            <button 
              onClick={() => onNavigate('scan')}
              className="group relative flex items-center justify-center size-16 rounded-full bg-gradient-to-br from-[#D0BB95] to-[#C0A070] text-[#1a1a2e] shadow-[0_0_25px_rgba(208,187,149,0.5)] transition-all hover:scale-105 active:scale-95 border-4 border-[#1e1e28]"
            >
              <span className="material-symbols-outlined text-3xl font-bold">document_scanner</span>
            </button>
          </div>

          {navItems.map((item, index) => {
            const isActive = currentScreen === item.screen;
            // Handle the gap for the scan button
            const isRightSide = index >= 2;

            return (
              <React.Fragment key={item.screen}>
                {index === 2 && <div className="w-12" />}
                <button
                  onClick={() => onNavigate(item.screen)}
                  className={`flex flex-col items-center gap-1 w-12 transition-colors ${isActive ? 'text-[#D0BB95]' : 'text-slate-500 hover:text-white'}`}
                >
                  <span className={`material-symbols-outlined ${isActive ? 'filled' : ''}`}>{item.icon}</span>
                  <span className={`text-[10px] ${isActive ? 'font-bold' : 'font-medium'}`}>{item.label}</span>
                </button>
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Navigation;

import React, { useState, useRef, useEffect } from 'react';
import { AppState, ChatMessage } from '../types';
import { getFinancialAdvice } from '../services/geminiService';

interface ChatProps {
  state: AppState;
  onBack: () => void;
}

const ChatScreen: React.FC<ChatProps> = ({ state, onBack }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: '1',
      role: 'model',
      text: "Namaste! I'm your Financial Guru. How can I help you save for that Gaming Laptop today?",
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const response = await getFinancialAdvice(input);
      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: response || "Hmm, something went wrong. Try again!",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden">
      <header className="glass p-4 border-b border-white/5 flex items-center gap-3">
        <button onClick={onBack} className="size-10 flex items-center justify-center rounded-full hover:bg-white/5 transition-colors">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className="size-10 rounded-full border border-white/10 bg-gradient-to-br from-primary to-slate-800 flex items-center justify-center">
              <span className="material-symbols-outlined text-white">smart_toy</span>
            </div>
            <div className="absolute bottom-0 right-0 size-3 bg-green-500 rounded-full border-2 border-background-dark"></div>
          </div>
          <div>
            <h2 className="text-white text-lg font-bold leading-tight">Financial Guru</h2>
            <div className="flex items-center gap-1">
              <span className="size-1.5 rounded-full bg-primary animate-pulse"></span>
              <p className="text-slate-400 text-xs font-medium">Online</p>
            </div>
          </div>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 pb-40 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-start gap-3 ${msg.role === 'user' ? 'justify-end' : ''}`}>
            {msg.role === 'model' && (
              <div className="shrink-0 mt-1 size-8 rounded-full bg-slate-800 border border-white/5 flex items-center justify-center">
                <span className="material-symbols-outlined text-xs text-primary">smart_toy</span>
              </div>
            )}
            <div className={`max-w-[85%] flex flex-col gap-1 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`px-5 py-3.5 rounded-2xl ${
                msg.role === 'user' 
                ? 'bg-primary text-background-dark rounded-tr-sm shadow-lg' 
                : 'bg-slate-800 text-white rounded-tl-sm border border-white/5'
              }`}>
                <p className="text-base font-medium leading-relaxed whitespace-pre-wrap">{msg.text}</p>
              </div>
              <p className="text-slate-500 text-[10px] px-1">
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex items-start gap-3">
            <div className="size-8 rounded-full bg-slate-800 border border-white/5 flex items-center justify-center animate-pulse">
              <span className="material-symbols-outlined text-xs text-primary">smart_toy</span>
            </div>
            <div className="bg-slate-800 px-5 py-3.5 rounded-2xl rounded-tl-sm border border-white/5 text-slate-400">
              Thinking...
            </div>
          </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-4 bg-background-dark/80 backdrop-blur-xl border-t border-white/5 z-50">
        <div className="max-w-md mx-auto flex items-center gap-2 glass p-1.5 rounded-[1.5rem] border border-white/10 shadow-lg">
          <button className="shrink-0 size-10 flex items-center justify-center rounded-full text-slate-400">
            <span className="material-symbols-outlined">add_circle</span>
          </button>
          <input 
            className="flex-1 bg-transparent border-none text-white placeholder-slate-500 focus:ring-0 text-[15px] font-medium"
            placeholder="Type a message or speak Hindi..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          />
          <button className="shrink-0 size-10 flex items-center justify-center rounded-full text-slate-400">
            <span className="material-symbols-outlined">mic</span>
          </button>
          <button 
            onClick={handleSend}
            disabled={loading}
            className={`shrink-0 size-10 flex items-center justify-center rounded-full text-white shadow-md transition-all ${loading ? 'bg-slate-700' : 'bg-primary text-background-dark'}`}
          >
            <span className="material-symbols-outlined font-bold">arrow_upward</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatScreen;

