import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

// Use API_KEY directly from process.env as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getFinancialAdvice = async (prompt: string, context: { transactions: any[], goals: any[] }) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      systemInstruction: `You are WiseupAI Financial Guru. 
      Context: User Transactions: ${JSON.stringify(context.transactions)}, Goals: ${JSON.stringify(context.goals)}.
      Style: Use Hinglish. Be friendly but cheeky. Roast impulsive spending. 
      Encourage saving for specific goals like Gaming Laptops.`,
      temperature: 0.8,
    }
  });

  // Directly access .text property
  return response.text;
};

export const analyzeReceipt = async (base64Image: string, goals: any[]) => {
  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image.split(',')[1],
    },
  };

  const textPart = {
    text: `Analyze this receipt image. Extract: Merchant Name, Total Amount, and Date. 
    Also categorize it and decide if it's 'Wise' (needs), 'Impulsive' (emotional wants), or 'Considerable' (planned wants).
    Finally, provide a witty Hinglish insight based on these goals: ${JSON.stringify(goals)}.
    Return as JSON.`
  };

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: { parts: [imagePart, textPart] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          merchant: { type: Type.STRING },
          amount: { type: Type.NUMBER },
          date: { type: Type.STRING },
          category: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Wise', 'Impulsive', 'Considerable'] },
          insight: { type: Type.STRING }
        },
        required: ["merchant", "amount", "date", "category", "type", "insight"]
      }
    }
  });

  // Directly access .text property
  return JSON.parse(response.text || '{}');
};

