import React, { useState, useRef, useEffect } from 'react';
import { AppState, ChatMessage } from '../types';
import { getFinancialAdvice } from '../services/geminiService';

interface ChatProps {
  state: AppState;
  onBack: () => void;
  initialQuery?: string | null;
  onClearInitialQuery?: () => void;
}

const ChatScreen: React.FC<ChatProps> = ({ state, onBack, initialQuery, onClearInitialQuery }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: '1',
      role: 'model',
      text: "Namaste! I'm your Financial Guru. How can I help you save for that Gaming Laptop today?",
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  // Handle initial query from dashboard
  useEffect(() => {
    if (initialQuery && !loading) {
      handleSend(initialQuery);
      onClearInitialQuery?.();
    }
  }, [initialQuery]);

  const handleSend = async (textToSend: string = input) => {
    const text = textToSend.trim();
    if (!text || loading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    if (!textToSend.trim().length === 0) setInput(''); // Only clear if it was from the input field
    if (textToSend === input) setInput(''); // Standard clear

    setLoading(true);

    try {
      const response = await getFinancialAdvice(text, { 
        transactions: state.transactions, 
        goals: state.goals 
      });
      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: response || "Hmm, something went wrong. Try again!",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (err) {
      console.error(err);
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: "Guru is feeling a bit tired. Check your connection and try again!",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden bg-background-light dark:bg-background-dark">
      <header className="glass p-4 border-b border-slate-200 dark:border-white/5 flex items-center gap-3 bg-white/80 dark:bg-background-dark/80 backdrop-blur-xl sticky top-0 z-10">
        <button onClick={onBack} className="size-10 flex items-center justify-center rounded-full hover:bg-slate-100 dark:hover:bg-white/5 transition-colors text-slate-800 dark:text-white">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className="size-10 rounded-full border border-primary/30 bg-gradient-to-br from-primary to-slate-800 flex items-center justify-center">
              <span className="material-symbols-outlined text-white">smart_toy</span>
            </div>
            <div className="absolute bottom-0 right-0 size-3 bg-green-500 rounded-full border-2 border-background-light dark:border-background-dark"></div>
          </div>
          <div>
            <h2 className="text-slate-900 dark:text-white text-lg font-bold leading-tight">Financial Guru</h2>
            <div className="flex items-center gap-1">
              <span className="size-1.5 rounded-full bg-primary animate-pulse"></span>
              <p className="text-slate-400 text-xs font-medium">Online</p>
            </div>
          </div>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 pb-40 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-start gap-3 ${msg.role === 'user' ? 'justify-end' : ''}`}>
            {msg.role === 'model' && (
              <div className="shrink-0 mt-1 size-8 rounded-full bg-slate-200 dark:bg-slate-800 border border-slate-300 dark:border-white/5 flex items-center justify-center">
                <span className="material-symbols-outlined text-xs text-primary">smart_toy</span>
              </div>
            )}
            <div className={`max-w-[85%] flex flex-col gap-1 ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`px-5 py-3.5 rounded-2xl ${
                msg.role === 'user' 
                ? 'bg-primary text-background-dark rounded-tr-sm shadow-md' 
                : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-white rounded-tl-sm border border-slate-200 dark:border-white/5 shadow-sm'
              }`}>
                <p className="text-[15px] font-medium leading-relaxed whitespace-pre-wrap">{msg.text}</p>
