interface ManualEntryProps {
  state: AppState;
  onBack: () => void;
  onAddTransaction: (tx: Transaction) => void;
}

const ManualEntryScreen: React.FC<ManualEntryProps> = ({ state, onBack, onAddTransaction }) => {
  const [merchant, setMerchant] = useState('');
  const [amount, setAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState<any>(null);

  const t = {
    ENG: {
      title: 'Manual Entry',
      merchantPlaceholder: 'Where did you spend?',
      amountPlaceholder: '0.00',
      analyze: 'Analyze Expense',
      confirm: 'Confirm & Add',
      discard: 'Discard',
      roastHeader: "Guru's Insight",
      waiting: 'Guru is thinking...'
    },
    HIN: {
      title: 'मैनुअल प्रविष्टि',
      merchantPlaceholder: 'आपने कहाँ खर्च किया?',
      amountPlaceholder: '0.00',
      analyze: 'खर्च का विश्लेषण करें',
      confirm: 'पुष्टि करें और जोड़ें',
      discard: 'रद्द करें',
      roastHeader: "गुरु की अंतर्दृष्टि",
      waiting: 'गुरु सोच रहा है...'
    }
  }[state.language];

  const handleAnalyze = async () => {
    if (!merchant || !amount || loading) return;
    setLoading(true);
    setAnalysis(null);
    try {
      const result = await classifyManualExpense(merchant, Number(amount), state.goals);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      // Fallback analysis
      setAnalysis({
        category: 'Shopping',
        type: 'Considerable',
        insight: "Bhai, manual entry mein bhi itna kharch? Category: Shopping, Tag: Considerable. Save for your goals instead!"
      });
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = () => {
    if (!analysis) return;
    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      merchant,
      amount: Number(amount),
      category: analysis.category,
      type: analysis.type,
      date: new Date().toLocaleDateString(),
      icon: 'receipt_long'
    };
    onAddTransaction(newTx);
    onBack();
  };

  return (
    <div className="flex-1 flex flex-col bg-[#050505] overflow-y-auto no-scrollbar pb-32">
      <header className="sticky top-0 z-50 p-6 flex items-center justify-between bg-black/40 backdrop-blur-xl border-b border-white/5">
        <h2 className="text-xl font-black uppercase tracking-[0.15em] text-white">{t.title}</h2>
        <button 
          onClick={onBack} 
          className="size-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center"
        >
           <span className="material-symbols-outlined text-white/70">close</span>
        </button>
      </header>

      <main className="p-6 space-y-8">
        <div className="space-y-6">
          <label className="block space-y-3">
             <p className="text-slate-500 text-[11px] font-black uppercase tracking-widest">{state.language === 'ENG' ? 'MERCHANT' : 'व्यापारी'}</p>
             <input 
              type="text"
              value={merchant}
              onChange={(e) => setMerchant(e.target.value)}
              placeholder={t.merchantPlaceholder}
              className="w-full bg-white/5 border border-white/10 text-white rounded-2xl h-14 px-5 text-base font-bold focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all"
             />
          </label>

          <label className="block space-y-3">
             <p className="text-slate-500 text-[11px] font-black uppercase tracking-widest">{state.language === 'ENG' ? 'AMOUNT' : 'राशि'}</p>
             <div className="relative">
               <span className="absolute left-5 top-1/2 -translate-y-1/2 text-primary font-black text-2xl">₹</span>
               <input 
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder={t.amountPlaceholder}
                className="w-full bg-white/5 border border-white/10 text-white rounded-2xl h-18 py-5 pl-12 pr-5 text-3xl font-black focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all"
               />
             </div>
          </label>

          <button 
            onClick={handleAnalyze}
            disabled={!merchant || !amount || loading}
            className={`w-full h-14 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${loading ? 'bg-white/10 text-white/40 cursor-not-allowed' : 'bg-primary text-background-dark shadow-xl shadow-primary/20 active:scale-95'}`}
          >
            {loading ? t.waiting : t.analyze}
          </button>
        </div>

        {analysis && (
          <div className="animate-in fade-in slide-in-from-bottom-5 space-y-6">
            <div className="bg-[#1a1814] rounded-[2.5rem] p-6 border border-white/5 space-y-4 shadow-2xl">
              <div className="flex items-center justify-between">
                <div>
                   <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">AUTO CATEGORY</p>
                   <p className="text-white font-black text-lg">{analysis.category}</p>
                </div>
                <div className="text-right">
                   <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">CLASSIFICATION</p>
                   <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${analysis.type === 'Wise' ? 'bg-wise/20 text-wise' : analysis.type === 'Impulsive' ? 'bg-impulsive/20 text-impulsive' : 'bg-primary/20 text-primary'}`}>
                      {analysis.type}
                   </span>
                </div>
              </div>

              <div className="h-px bg-white/5"></div>

              <div className="space-y-3">
                 <div className="flex items-center gap-2">
                   <span className="material-symbols-outlined text-primary text-lg">psychology</span>
                   <p className="text-primary text-[10px] font-black uppercase tracking-widest">{t.roastHeader}</p>
                 </div>
                 <p className="text-slate-300 italic text-sm leading-relaxed font-medium">
                    "{analysis.insight}"
                 </p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
               <button onClick={() => setAnalysis(null)} className="h-14 rounded-2xl border border-white/10 text-white font-black text-xs uppercase tracking-widest">
                  {t.discard}
               </button>
               <button onClick={handleConfirm} className="h-14 rounded-2xl bg-primary text-background-dark font-black text-xs uppercase tracking-widest shadow-xl shadow-primary/20">
                  {t.confirm}
               </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default ManualEntryScreen;

import React, { useRef, useEffect, useState } from 'react';

interface ScanScreenProps {
  onCapture: (image: string) => void;
  onBack: () => void;
}

const ScanScreen: React.FC<ScanScreenProps> = ({ onCapture, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const isStartingRef = useRef(false);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  const startCamera = async () => {
    if (isStartingRef.current) return;
    isStartingRef.current = true;
    setError(null);

    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("Camera API not supported in this browser.");
      }

      // Stop any existing tracks before starting a new stream
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }

      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { 
          facingMode: 'environment',
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        },
        audio: false
      });

      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
    } catch (err: any) {
      console.error("Camera error detail:", err);

      let message = "Could not access camera.";

      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError' || err.message?.toLowerCase().includes('denied')) {
        message = "Camera access was denied. Please check your browser's site settings to allow camera access for this app, then try again.";
      } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
        message = "No camera was found on this device.";
      } else if (err.name === 'NotReadableError' || err.name === 'TrackStartError') {
        message = "Camera is already in use by another application.";
      } else {
        message = err.message || "An unexpected camera error occurred.";
      }

      setError(message);
    } finally {
      isStartingRef.current = false;
    }
  };

  useEffect(() => {
    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const takePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // Use video display size for canvas
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.9);
        onCapture(dataUrl);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col">
      <div className="absolute top-0 inset-x-0 z-50 p-6 flex items-center justify-between bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onBack} className="size-10 flex items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20 transition-colors">
          <span className="material-symbols-outlined">close</span>
        </button>
        <p className="text-white font-bold text-sm tracking-widest uppercase">Scan Receipt</p>
        <div className="size-10"></div>
      </div>

      <div className="flex-1 relative overflow-hidden flex items-center justify-center">
        {error ? (
          <div className="p-8 text-center flex flex-col items-center gap-6 z-10 max-w-sm animate-in fade-in zoom-in">
            <div className="size-20 rounded-full bg-red-500/10 flex items-center justify-center text-red-500 mb-2">
              <span className="material-symbols-outlined text-5xl">videocam_off</span>
            </div>
            <h3 className="text-white text-xl font-bold tracking-tight">Camera Error</h3>
            <p className="text-slate-400 text-sm leading-relaxed">
              {error}
            </p>
            <div className="flex flex-col w-full gap-3">
              <button 
                onClick={startCamera}
                className="bg-primary text-background-dark font-black px-8 py-4 rounded-2xl active:scale-95 transition-all shadow-xl shadow-primary/20"
              >
                Try Again
              </button>
              <button 
                onClick={onBack}
                className="text-white/40 text-sm font-bold uppercase tracking-widest hover:text-white transition-colors py-2"
              >
                Go Back
              </button>
            </div>
          </div>
        ) : (
          <>
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted
              className="h-full w-full object-cover"
            />

            {/* Scanner UI Overlay */}
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="w-[80%] aspect-[3/4] border-2 border-primary/30 rounded-[2rem] relative">
                {/* Corner Accents */}
                <div className="absolute -top-1 -left-1 size-12 border-t-4 border-l-4 border-primary rounded-tl-2xl"></div>
                <div className="absolute -top-1 -right-1 size-12 border-t-4 border-r-4 border-primary rounded-tr-2xl"></div>
                <div className="absolute -bottom-1 -left-1 size-12 border-b-4 border-l-4 border-primary rounded-bl-2xl"></div>
                <div className="absolute -bottom-1 -right-1 size-12 border-b-4 border-r-4 border-primary rounded-br-2xl"></div>

                {/* Animated Scanning Line */}
                <div className="absolute top-0 left-0 w-full h-1 bg-primary/60 shadow-[0_0_20px_rgba(208,187,149,0.8)] animate-[scan_2.5s_infinite_ease-in-out]"></div>
              </div>
            </div>

            <div className="absolute bottom-10 inset-x-0 flex flex-col items-center gap-8">
              <div className="bg-black/60 backdrop-blur-xl px-6 py-2.5 rounded-full border border-white/10 shadow-2xl">
                <p className="text-white/80 text-[10px] font-black uppercase tracking-[0.2em]">
                  Align receipt within frame
                </p>
              </div>

              <button 
                onClick={takePhoto}
                className="group relative size-24 rounded-full border-4 border-white/30 flex items-center justify-center active:scale-90 transition-all duration-300"
              >
                <div className="size-20 rounded-full bg-white shadow-2xl group-hover:scale-105 transition-transform"></div>
                <div className="absolute inset-0 rounded-full border-2 border-white scale-110 opacity-0 group-active:opacity-100 group-active:scale-100 transition-all"></div>
              </button>
            </div>
          </>
        )}
      </div>

      <canvas ref={canvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 5%; opacity: 0.3; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { top: 95%; opacity: 0.3; }
        }
      `}</style>
    </div>
  );
};

export default ScanScreen;

import React, { useState, useRef, useEffect } from 'react';
import { AppState } from '../types';

interface NavigationProps {
  currentScreen: AppState['currentScreen'];
  onNavigate: (screen: AppState['currentScreen']) => void;
}

const Navigation: React.FC<NavigationProps> = ({ currentScreen, onNavigate }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  const navItems: { screen: AppState['currentScreen']; label: string; icon: string }[] = [
    { screen: 'dashboard', label: 'Home', icon: 'home' },
    { screen: 'analytics', label: 'Stats', icon: 'analytics' },
    { screen: 'chat', label: 'Guru', icon: 'psychology' },
    { screen: 'offers', label: 'Offers', icon: 'local_offer' },
  ];

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 flex flex-col items-center pointer-events-none">
      <div className="w-full max-w-md pointer-events-auto relative" ref={menuRef}>

        {/* Expanded Menu Options */}
        {isMenuOpen && (
          <div className="absolute -top-36 left-1/2 transform -translate-x-1/2 flex flex-col gap-3 animate-in fade-in slide-in-from-bottom-5 duration-300">
            <button 
              onClick={() => { onNavigate('manual_entry'); setIsMenuOpen(false); }}
              className="flex items-center gap-3 bg-[#1a1814] border border-white/10 px-5 py-3 rounded-2xl shadow-2xl transition-all hover:bg-[#25221d] active:scale-95"
            >
              <div className="size-8 rounded-lg bg-primary/20 flex items-center justify-center text-primary">
                <span className="material-symbols-outlined text-xl">edit_note</span>
              </div>
              <span className="text-white text-xs font-black uppercase tracking-widest whitespace-nowrap">Add Manually</span>
            </button>
            <button 
              onClick={() => { onNavigate('scan'); setIsMenuOpen(false); }}
              className="flex items-center gap-3 bg-[#1a1814] border border-white/10 px-5 py-3 rounded-2xl shadow-2xl transition-all hover:bg-[#25221d] active:scale-95"
            >
              <div className="size-8 rounded-lg bg-primary/20 flex items-center justify-center text-primary">
                <span className="material-symbols-outlined text-xl">photo_camera</span>
              </div>
              <span className="text-white text-xs font-black uppercase tracking-widest whitespace-nowrap">Scan Bill</span>
            </button>
          </div>
        )}

        <div className="relative glass pb-8 pt-3 px-6 flex items-center justify-between border-t border-white/5 bg-[#0a0a0f]/90 backdrop-blur-2xl">
          {/* Floating Action Button */}
          <div className="absolute -top-10 left-1/2 transform -translate-x-1/2">
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className={`group relative flex items-center justify-center size-16 rounded-full bg-gradient-to-br from-[#D0BB95] to-[#C0A070] text-[#1a1a2e] shadow-[0_0_30px_rgba(208,187,149,0.4)] transition-all active:scale-95 border-4 border-[#0a0a0f] ${isMenuOpen ? 'rotate-45' : ''}`}
            >
              <span className="material-symbols-outlined text-3xl font-bold">
                {isMenuOpen ? 'close' : 'receipt_long'}
              </span>
            </button>
          </div>

          {navItems.map((item, index) => {
            const isActive = currentScreen === item.screen;

            return (
              <React.Fragment key={item.screen}>
                {index === 2 && <div className="w-12" />}
                <button
                  onClick={() => { onNavigate(item.screen); setIsMenuOpen(false); }}
                  className={`flex flex-col items-center gap-1 w-12 transition-all ${isActive ? 'text-[#D0BB95] scale-110' : 'text-slate-500 hover:text-white'}`}
                >
                  <span className={`material-symbols-outlined ${isActive ? 'filled' : ''}`}>{item.icon}</span>
                  <span className={`text-[10px] tracking-tight ${isActive ? 'font-black' : 'font-bold'}`}>{item.label}</span>
                  {isActive && <div className="w-1 h-1 bg-primary rounded-full absolute -bottom-1"></div>}
                </button>
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Navigation;

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

// Use API_KEY directly from process.env as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getFinancialAdvice = async (prompt: string, context: { transactions: any[], goals: any[], monthlyAllowance: number }) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      systemInstruction: `You are WiseupAI Financial Guru. 
      Context: User Transactions: ${JSON.stringify(context.transactions)}, Goals: ${JSON.stringify(context.goals)}, Monthly Allowance: ₹${context.monthlyAllowance}.
      Persona: You are a sharp, witty, and slightly judgemental Indian financial expert. 
      Style: Use Hinglish (mixture of Hindi and English). 
      Classification Rules:
      1. Wise: Essential needs, savings, or study-related expenses that are reasonable.
      2. Considerable: Non-essential spends exceeding 15% of the monthly allowance (₹${context.monthlyAllowance * 0.15}).
      3. Impulsive: Spends exceeding 35% of the monthly allowance (₹${context.monthlyAllowance * 0.35}) OR clearly emotional luxury buys.
      Constraint: Keep advice/roasts to exactly 4-6 impact-ful lines. 
      End with a cheeky motivational tip about their biggest goal.`,
      temperature: 0.9,
    }
  });

  return response.text;
};

export const analyzeReceipt = async (base64Image: string, context: { goals: any[], monthlyAllowance: number }) => {
  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image.split(',')[1],
    },
  };

  const textPart = {
    text: `Analyze this receipt image. Extract: Merchant Name, Total Amount, and Date. 
    Monthly Allowance: ₹${context.monthlyAllowance}.

    Classification Logic:
    - 'Wise': Essentials, savings, or study-related items.
    - 'Considerable': Non-essential spends > 15% of allowance (₹${context.monthlyAllowance * 0.15}).
    - 'Impulsive': Spends > 35% of allowance (₹${context.monthlyAllowance * 0.35}) or pure emotional wants.

    Goals: ${JSON.stringify(context.goals)}.
    Return as JSON.`
  };

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: { parts: [imagePart, textPart] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          merchant: { type: Type.STRING },
          amount: { type: Type.NUMBER },
          date: { type: Type.STRING },
          category: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Wise', 'Impulsive', 'Considerable'] },
          insight: { type: Type.STRING }
        },
        required: ["merchant", "amount", "date", "category", "type", "insight"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const classifyManualExpense = async (merchant: string, amount: number, context: { goals: any[], monthlyAllowance: number }) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Classify manual expense: Merchant: "${merchant}", Amount: ₹${amount}. 
    User Monthly Allowance: ₹${context.monthlyAllowance}.

    Rules:
    - 'Wise': Studying, saving, essentials.
    - 'Considerable': If non-essential and > 15% of allowance (₹${context.monthlyAllowance * 0.15}).
    - 'Impulsive': If > 35% of allowance (₹${context.monthlyAllowance * 0.35}).

    Goals: ${JSON.stringify(context.goals)}. Provide witty Hinglish insight.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Wise', 'Impulsive', 'Considerable'] },
          insight: { type: Type.STRING }
        },
        required: ["category", "type", "insight"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

import React, { useState, useEffect } from 'react';
import { AppState, Transaction } from '../types';
import { analyzeReceipt } from '../services/geminiService';

interface ScanProps {
  state: AppState;
  scannedImage: string | null;
  onBack: () => void;
  onAddTransaction: (tx: Transaction) => void;
}

const ScanResultScreen: React.FC<ScanProps> = ({ state, scannedImage, onBack, onAddTransaction }) => {
  const [loading, setLoading] = useState(true);
  const [result, setResult] = useState<any>(null);

  useEffect(() => {
    const processReceipt = async () => {
      if (!scannedImage) return;
      try {
        const analysis = await analyzeReceipt(scannedImage, { 
          goals: state.goals, 
          monthlyAllowance: state.monthlyAllowance 
        });
        setResult(analysis);
      } catch (err) {
        console.error("AI Analysis failed:", err);
        setResult({
          merchant: "Merchant Detected",
          amount: 450,
          date: new Date().toLocaleDateString(),
          category: "Food & Drinks",
          type: "Impulsive",
          insight: "Arre yaar, analysis fail ho gaya but Guru knows this looks like an impulse buy! Try to resist the urge next time."
        });
      } finally {
        setLoading(false);
      }
    };
    processReceipt();
  }, [scannedImage]);

  const handleConfirm = () => {
    if (!result) return;
    const newTx: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      merchant: result.merchant,
      amount: result.amount,
      category: result.category,
      type: result.type,
      date: result.date,
      icon: result.category.toLowerCase().includes('food') ? 'restaurant' : 'shopping_bag',
      imageUrl: scannedImage || undefined
    };
    onAddTransaction(newTx);
    onBack();
  };

  return (
    <div className="flex-1 flex flex-col bg-background-dark overflow-y-auto no-scrollbar pb-32">
      <div className="fixed top-0 left-0 right-0 z-50 flex items-center justify-between p-5 bg-background-dark/80 backdrop-blur-xl border-b border-white/5">
        <button onClick={onBack} className="text-white flex size-10 items-center justify-center rounded-full bg-white/5 transition-colors">
          <span className="material-symbols-outlined">close</span>
        </button>
        <h2 className="text-white text-base font-black uppercase tracking-widest">AI Bill Scanner</h2>
        <div className="w-10"></div>
      </div>

      <div className="h-[76px]"></div>

      <main className="flex-1 flex flex-col p-5 gap-8">
        <div className="relative rounded-[2.5rem] overflow-hidden aspect-[4/5] shadow-2xl group border border-white/10">
          <img 
            src={scannedImage || "https://picsum.photos/seed/receipt/800/1000"} 
            className={`w-full h-full object-cover transition-all duration-700 ${loading ? 'scale-110 blur-sm brightness-50' : 'scale-100'}`} 
