            <button 
              onClick={() => handleSend()}
              disabled={loading}
              className={`shrink-0 size-11 flex items-center justify-center rounded-full shadow-lg transition-all ${loading ? 'bg-white/10 cursor-not-allowed text-white/20' : 'bg-primary text-background-dark hover:scale-105 active:scale-95'}`}
            >
              <span className="material-symbols-outlined font-black">arrow_upward</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

