import React, { useState, useEffect } from 'react';
import WelcomeScreen from './screens/WelcomeScreen';
import SetupScreen from './screens/SetupScreen';
import DashboardScreen from './screens/DashboardScreen';
import AnalyticsScreen from './screens/AnalyticsScreen';
import ToolsScreen from './screens/ToolsScreen';
import ChatScreen from './screens/ChatScreen';
import OffersScreen from './screens/OffersScreen';
import SettingsScreen from './screens/SettingsScreen';
import ScanScreen from './screens/ScanScreen';
import ScanResultScreen from './screens/ScanResultScreen';
import ManualEntryScreen from './screens/ManualEntryScreen';
import Navigation from './components/Navigation';
import { AppState, Goal, Transaction } from './types';

const INITIAL_GOALS: Goal[] = [];
const INITIAL_TRANSACTIONS: Transaction[] = [];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: { name: 'User', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=FreshStart' },
    language: 'ENG',
    isDarkMode: true,
    monthlyAllowance: 0,
    transactions: INITIAL_TRANSACTIONS,
    goals: INITIAL_GOALS,
    currentScreen: 'welcome'
  });

  const [scannedImage, setScannedImage] = useState<string | null>(null);
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // Sync theme with document element
  useEffect(() => {
    if (state.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state.isDarkMode]);

  const updateScreen = (screen: AppState['currentScreen']) => {
    setState(prev => ({ ...prev, currentScreen: screen }));
  };

  const handleDashboardAction = (screen: AppState['currentScreen'], query?: string) => {
    if (query) setPendingChatQuery(query);
    updateScreen(screen);
  };

  const handleAddTransaction = (tx: Transaction) => {
    setState(prev => ({
      ...prev,
      transactions: [tx, ...prev.transactions]
    }));
  };

  const setAllowance = (amount: number) => {
    setState(prev => ({ ...prev, monthlyAllowance: amount, currentScreen: 'dashboard' }));
  };

  const handleScanComplete = (image: string) => {
    setScannedImage(image);
    updateScreen('scan');
  };

  const toggleLanguage = () => {
    setState(prev => ({ ...prev, language: prev.language === 'ENG' ? 'HIN' : 'ENG' }));
  };

  const toggleDarkMode = () => {
    setState(prev => ({ ...prev, isDarkMode: !prev.isDarkMode }));
  };

  const renderScreen = () => {
    switch (state.currentScreen) {
      case 'welcome':
        return <WelcomeScreen language={state.language} onToggleLang={toggleLanguage} onContinue={() => updateScreen('setup')} />;
      case 'setup':
        return <SetupScreen state={state} onSave={setAllowance} />;
      case 'dashboard':
        return <DashboardScreen state={state} onAction={handleDashboardAction} />;
      case 'analytics':
        return <AnalyticsScreen state={state} onBack={() => updateScreen('dashboard')} onAction={handleDashboardAction} />;
      case 'tools':
        return <ToolsScreen state={state} onBack={() => updateScreen('dashboard')} />;
      case 'chat':
        return (
          <ChatScreen 
            state={state} 
            onBack={() => updateScreen('dashboard')} 
            initialQuery={pendingChatQuery} 
            onClearInitialQuery={() => setPendingChatQuery(null)}
          />
        );
      case 'offers':
        return <OffersScreen state={state} onBack={() => updateScreen('dashboard')} onNavigate={updateScreen} />;
      case 'scan':
        return <ScanResultScreen state={state} scannedImage={scannedImage} onBack={() => updateScreen('dashboard')} onAddTransaction={handleAddTransaction} />;
      case 'manual_entry':
        return <ManualEntryScreen state={state} onBack={() => updateScreen('dashboard')} onAddTransaction={handleAddTransaction} />;
      case 'settings':
        return (
          <SettingsScreen 
            state={state} 
            onBack={() => updateScreen('dashboard')} 
            onLogout={() => updateScreen('welcome')} 
            onToggleLang={toggleLanguage} 
            onToggleTheme={toggleDarkMode}
          />
        );
      default:
        return <DashboardScreen state={state} onAction={handleDashboardAction} />;
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-background-light dark:bg-[#050505] transition-colors duration-300">
      <div className="w-full max-w-md relative flex flex-col bg-background-light dark:bg-background-dark shadow-2xl overflow-hidden min-h-screen">
        {state.currentScreen === 'scan' && !scannedImage ? (
           <ScanScreen onBack={() => updateScreen('dashboard')} onCapture={handleScanComplete} />
        ) : (
          renderScreen()
        )}

        {['dashboard', 'analytics', 'tools', 'chat', 'offers'].includes(state.currentScreen) && (
          <Navigation currentScreen={state.currentScreen} onNavigate={(screen) => {
            if (screen === 'scan') setScannedImage(null);
            updateScreen(screen);
          }} />
        )}
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

// Use API_KEY directly from process.env as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getFinancialAdvice = async (prompt: string, context: { transactions: any[], goals: any[], monthlyAllowance: number }) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      systemInstruction: `You are WiseupAI Financial Guru. 
      Context: User Transactions: ${JSON.stringify(context.transactions)}, Goals: ${JSON.stringify(context.goals)}, Monthly Allowance: ₹${context.monthlyAllowance}.
      Persona: You are a sharp, witty, and slightly judgemental Indian financial expert. However, if the user explicitly requests a "professional" tone or "formal analysis," switch to a polished, helpful, and sophisticated professional persona.
      Style: By default, use Hinglish (mixture of Hindi and English). If requested "in English" or for a "professional" report, respond strictly in clear, professional English.

      Classification Protocol:
      - 'Wise': Spends on saving, studying, or essentials that are "not much" (under 15% of allowance: ₹${context.monthlyAllowance * 0.15}).
      - 'Considerable': Non-essential spends that exceed 15% of monthly allowance (₹${context.monthlyAllowance * 0.15}).
      - 'Impulsive': Spends that exceed 35% of monthly allowance (₹${context.monthlyAllowance * 0.35}) OR clearly emotional luxury purchases.

      Constraint: When roasting/witty, keep it to exactly 4-6 lines. When providing professional analysis, be concise but thorough.
      Always try to provide actionable saving advice based on the user's biggest goal.`,
      temperature: 0.7,
    }
  });

  return response.text;
};

export const analyzeReceipt = async (base64Image: string, context: { goals: any[], monthlyAllowance: number }) => {
  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image.split(',')[1],
    },
  };

  const textPart = {
    text: `Analyze this receipt image. Extract: Merchant Name, Total Amount, and Date. 
    Monthly Allowance: ₹${context.monthlyAllowance}.

    Apply this Classification Logic:
    1. 'Wise': Essential needs, saving, or study items AND amount is <= 15% of allowance (₹${context.monthlyAllowance * 0.15}).
    2. 'Considerable': Non-essential items AND amount > 15% of allowance (₹${context.monthlyAllowance * 0.15}).
    3. 'Impulsive': Any spend > 35% of allowance (₹${context.monthlyAllowance * 0.35}).

    Goals: ${JSON.stringify(context.goals)}.
    Return as JSON.`
  };

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: { parts: [imagePart, textPart] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          merchant: { type: Type.STRING },
          amount: { type: Type.NUMBER },
          date: { type: Type.STRING },
          category: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Wise', 'Impulsive', 'Considerable'] },
          insight: { type: Type.STRING }
        },
        required: ["merchant", "amount", "date", "category", "type", "insight"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

