import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

// Use API_KEY directly from process.env as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getFinancialAdvice = async (prompt: string, context: { transactions: any[], goals: any[], monthlyAllowance: number }) => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      systemInstruction: `You are WiseupAI Financial Guru. 
      Context: User Transactions: ${JSON.stringify(context.transactions)}, Goals: ${JSON.stringify(context.goals)}, Monthly Allowance: ₹${context.monthlyAllowance}.

      Persona & Language Protocol:
      1. Default Mode: A sharp, witty, and slightly judgemental Indian financial expert. Uses "Hinglish" (Hindi + English).
      2. Professional Mode: If the prompt contains keywords like "professional", "formal", "report", or "analyze" AND specifies "English", switch to a polished, sophisticated, and helpful Financial Advisor persona. In this mode, avoid Hinglish and slang; use clear, structured, and formal English.

      Analysis Requirements for Professional Mode:
      - Categorize spending into Travel, Shopping, Entertainment, Study, etc.
      - Identify peak expenditure dates.
      - Calculate and mention the longest saving streak found in the logs.

      Classification Rules:
      - 'Wise': Essentials/saving/study < 15% of allowance (₹${context.monthlyAllowance * 0.15}).
      - 'Considerable': Non-essentials > 15% of allowance (₹${context.monthlyAllowance * 0.15}).
      - 'Impulsive': Spends > 35% of allowance (₹${context.monthlyAllowance * 0.35}) or emotional buys.

      Always provide actionable advice to help the user reach their top financial goal.`,
      temperature: 0.7,
    }
  });

  return response.text;
};

export const analyzeReceipt = async (base64Image: string, context: { goals: any[], monthlyAllowance: number }) => {
  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image.split(',')[1],
    },
  };

  const textPart = {
    text: `Analyze this receipt image. Extract: Merchant Name, Total Amount, and Date. 
    Monthly Allowance: ₹${context.monthlyAllowance}.

    Apply this Classification Logic:
    1. 'Wise': Essential needs, saving, or study items AND amount is <= 15% of allowance (₹${context.monthlyAllowance * 0.15}).
    2. 'Considerable': Non-essential items AND amount > 15% of allowance (₹${context.monthlyAllowance * 0.15}).
    3. 'Impulsive': Any spend > 35% of allowance (₹${context.monthlyAllowance * 0.35}).

    Goals: ${JSON.stringify(context.goals)}.
    Return as JSON.`
  };

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: { parts: [imagePart, textPart] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          merchant: { type: Type.STRING },
          amount: { type: Type.NUMBER },
          date: { type: Type.STRING },
          category: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Wise', 'Impulsive', 'Considerable'] },
          insight: { type: Type.STRING }
        },
        required: ["merchant", "amount", "date", "category", "type", "insight"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const classifyManualExpense = async (merchant: string, amount: number, context: { goals: any[], monthlyAllowance: number }) => {
