  const monthNames = useMemo(() => {
    const months = [];
    for (let i = 2; i >= 0; i--) {
      const d = new Date();
      d.setMonth(d.getMonth() - i);
      months.push(d.toLocaleString('default', { month: 'long' }).toUpperCase());
    }
    return months;
  }, []);

  const [selectedMonthIndex, setSelectedMonthIndex] = useState(2); // Default to current month (last in array)
  const currentMonthName = monthNames[selectedMonthIndex];

  // Map month name to actual Date object for filtering
