import React, { useState, useMemo } from 'react';
import { AppState } from '../types';

interface AnalyticsProps {
  state: AppState;
  onBack: () => void;
  onAction: (screen: AppState['currentScreen'], query?: string) => void;
}

const AnalyticsScreen: React.FC<AnalyticsProps> = ({ state, onBack, onAction }) => {
  const monthNames = useMemo(() => {
    const months = [];
    for (let i = 2; i >= 0; i--) {
      const d = new Date();
      d.setMonth(d.getMonth() - i);
      months.push(d.toLocaleString('default', { month: 'long' }).toUpperCase());
    }
    return months;
  }, []);

  const [selectedMonthIndex, setSelectedMonthIndex] = useState(2);
  const currentMonthName = monthNames[selectedMonthIndex];

  const selectedDateContext = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - (2 - selectedMonthIndex));
    return { month: d.getMonth(), year: d.getFullYear() };
  }, [selectedMonthIndex]);

  const filteredTransactions = useMemo(() => {
    return state.transactions.filter(tx => {
      const d = new Date(tx.date);
      return d.getMonth() === selectedDateContext.month && d.getFullYear() === selectedDateContext.year;
    });
  }, [state.transactions, selectedDateContext]);

  const totalSpent = filteredTransactions.reduce((acc, curr) => acc + curr.amount, 0);
  const impulsiveSpent = filteredTransactions.filter(t => t.type === 'Impulsive').reduce((acc, curr) => acc + curr.amount, 0);
  const considerableSpent = filteredTransactions.filter(t => t.type === 'Considerable').reduce((acc, curr) => acc + curr.amount, 0);
  const wiseSpent = filteredTransactions.filter(t => t.type === 'Wise').reduce((acc, curr) => acc + curr.amount, 0);

  const impulsiveCount = filteredTransactions.filter(t => t.type === 'Impulsive').length;

  const streak = useMemo(() => {
    if (filteredTransactions.length === 0) return 0;
    return filteredTransactions.filter(t => t.type === 'Wise').length;
  }, [filteredTransactions]);

  const t = {
    ENG: {
      analysis: 'ANALYSIS',
      title: 'Spending Habits',
      totalSpent: 'TOTAL SPENT',
      impulsive: 'IMPULSIVE ITEMS',
      streak: 'STREAK',
      days: 'Days',
      breakdown: 'SPENDING CLASSES',
      aiInsight: 'AI INSIGHT',
      insightText: state.transactions.length > 0 
        ? 'Guru has detected patterns in your spending. Tap to get a deep dive and saving plan!'
        : 'Start logging your expenses to see AI-driven financial insights here.',
      history: 'RECENT HISTORY',
      viewAll: 'VIEW ALL',
      insightPrompt: `Guru, please provide a professional and helpful analysis of my spending patterns strictly in English...`
    },
    HIN: {
      analysis: 'विश्लेषण',
      title: 'खर्च की आदतें',
      totalSpent: 'कुल खर्च',
      impulsive: 'लापरवाह वस्तुएं',
      streak: 'लगातार',
      days: 'दिन',
      breakdown: 'खर्च श्रेणियां',
      aiInsight: 'AI अंतर्दृष्टि',
      insightText: state.transactions.length > 0 
        ? 'गुरु ने आपके खर्चों में पैटर्न देखा है। गहरी जानकारी के लिए टैप करें!'
        : 'यहां AI-संचालित वित्तीय अंतर्दृष्टि देखने के लिए अपने खर्चों को लॉग करना शुरू करें।',
      history: 'हालिया इतिहास',
      viewAll: 'सभी देखें',
      insightPrompt: `Guru, I would like a formal analysis in English...`
    }
  }[state.language];

  const heatmapData = useMemo(() => {
    const daysInMonth = new Date(selectedDateContext.year, selectedDateContext.month + 1, 0).getDate();
    return Array.from({ length: 31 }, (_, i) => {
      const day = i + 1;
      if (day > daysInMonth) return { day, hasSpend: false, isImpulsive: false, dailyTotal: 0, inactive: true };
      const dayTransactions = filteredTransactions.filter(tx => new Date(tx.date).getDate() === day);
      return { 
        day, 
        hasSpend: dayTransactions.length > 0, 
        isImpulsive: dayTransactions.some(tx => tx.type === 'Impulsive'), 
        dailyTotal: dayTransactions.reduce((sum, tx) => sum + tx.amount, 0),
        inactive: false 
      };
    });
  }, [filteredTransactions, selectedDateContext]);

  // Pie chart calculation
  const pieData = useMemo(() => {
    if (totalSpent === 0) return { impulsive: 33.3, considerable: 33.3, wise: 33.4 };
    return {
      impulsive: (impulsiveSpent / totalSpent) * 100,
      considerable: (considerableSpent / totalSpent) * 100,
      wise: (wiseSpent / totalSpent) * 100
    };
  }, [totalSpent, impulsiveSpent, considerableSpent, wiseSpent]);

  return (
    <div className="flex-1 flex flex-col bg-[#0d0c0b] overflow-y-auto no-scrollbar pb-32">
      <header className="sticky top-0 z-20 bg-[#0d0c0b] p-6 pb-2">
        <div className="flex flex-col mb-6">
          <span className="text-[10px] font-black text-[#D0BB95]/60 uppercase tracking-[0.2em] mb-1">{t.analysis}</span>
          <h2 className="text-3xl font-black tracking-tight text-white">{t.title}</h2>
        </div>
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 items-center">
          {monthNames.map((m, i) => (
            <button 
              key={m} 
              onClick={() => setSelectedMonthIndex(i)}
              className={`flex h-11 shrink-0 items-center justify-center rounded-xl px-6 transition-all text-[11px] font-black uppercase tracking-widest border ${selectedMonthIndex === i ? 'bg-[#1a1814] border-white/10 text-white' : 'bg-transparent border-transparent text-slate-600'}`}
            >
              {m}
            </button>
          ))}
          <div className="w-[4px] h-8 bg-[#D0BB95] rounded-full shrink-0 ml-2"></div>
        </div>
      </header>

      <main className="p-5 space-y-6">
        {/* Heatmap Section */}
        <section className="bg-[#121110] rounded-[2.5rem] p-6 border border-white/5 shadow-2xl">
          <div className="grid grid-cols-7 gap-1.5">
            {heatmapData.map(item => (
              <div 
                key={item.day}
                className={`aspect-square rounded-lg flex items-center justify-center text-[10px] font-black transition-all ${
                  item.inactive 
                    ? 'bg-transparent text-transparent'
                    : item.isImpulsive 
                      ? 'bg-red-500 text-white' 
                      : item.hasSpend 
                        ? 'bg-[#2a2722] text-[#D0BB95] border border-[#D0BB95]/30'
                        : 'bg-[#1a1816] text-slate-700'
                }`}
              >
                {item.day}
              </div>
            ))}
          </div>
        </section>

        {/* Stats Grid */}
        <section className="grid grid-cols-3 gap-3">
          <div className="flex flex-col gap-2 rounded-3xl p-4 bg-[#141311] border border-white/5 shadow-xl min-h-[110px] justify-center text-center">
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{t.totalSpent}</p>
            <p className="text-xl font-black text-white tracking-tighter">₹{totalSpent.toLocaleString()}</p>
          </div>
          <div className="flex flex-col gap-2 rounded-3xl p-4 bg-[#1a1313] border border-red-900/10 shadow-xl min-h-[110px] justify-center text-center">
            <p className="text-[9px] font-black text-red-400 uppercase tracking-widest">{t.impulsive}</p>
            <p className="text-2xl font-black text-red-500 tracking-tighter">{impulsiveCount}</p>
          </div>
          <div className="flex flex-col gap-2 rounded-3xl p-4 bg-[#131a13] border border-green-900/10 shadow-xl min-h-[110px] justify-center text-center">
            <p className="text-[9px] font-black text-green-400 uppercase tracking-widest">{t.streak}</p>
            <p className="text-xl font-black text-green-500 tracking-tighter">{streak} {t.days}</p>
          </div>
        </section>

        {/* Spending Classes Breakdown (Pie Chart) */}
        <section className="bg-[#121110] rounded-[2.5rem] p-7 border border-white/5 shadow-2xl space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-white text-sm font-black uppercase tracking-widest">{t.breakdown}</h3>
            <span className="material-symbols-outlined text-primary">pie_chart</span>
          </div>

          <div className="flex items-center gap-8">
