/**
 * Firebase keys strictly require an "AIza" prefix for the SDK to even initialize.
 * Since process.env.API_KEY is the exclusive source for keys in this environment, 
 * we must ensure it doesn't cause a crash if it's not a native Firebase key.
 */
const getSafeApiKey = () => {
  const key = process.env.API_KEY;
  if (key && typeof key === 'string' && key.startsWith('AIza')) {
    return key;
  }
  // Return a syntactically valid placeholder to bypass SDK initialization checks.
  // This prevents the "auth/api-key-not-valid" initialization crash.
  return "AIzaSyPlaceholder_FirebaseConfigRequired_Using_GenAI_Key_Instead";
};

