import React, { useState, useEffect } from 'react';
import WelcomeScreen from './screens/WelcomeScreen';
import SetupScreen from './screens/SetupScreen';
import DashboardScreen from './screens/DashboardScreen';
import AnalyticsScreen from './screens/AnalyticsScreen';
import ToolsScreen from './screens/ToolsScreen';
import ChatScreen from './screens/ChatScreen';
import OffersScreen from './screens/OffersScreen';
import SettingsScreen from './screens/SettingsScreen';
import ScanScreen from './screens/ScanScreen';
import ScanResultScreen from './screens/ScanResultScreen';
import ManualEntryScreen from './screens/ManualEntryScreen';
import Navigation from './components/Navigation';
import { AppState, Goal, Transaction } from './types';
import { onAuthStateChanged, signOut, loadUserData, saveUserData } from './services/firebase';

const INITIAL_GOALS: Goal[] = [];
const INITIAL_TRANSACTIONS: Transaction[] = [];
const DEFAULT_AVATAR = 'https://i.ibb.co/L5Vb7N5/thug-life-avatar.jpg';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: { 
      name: 'Guest', 
      avatar: DEFAULT_AVATAR 
    },
    language: 'ENG',
    isDarkMode: true,
    monthlyAllowance: 0,
    transactions: INITIAL_TRANSACTIONS,
    goals: INITIAL_GOALS,
    currentScreen: 'welcome'
  });

  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [scannedImage, setScannedImage] = useState<string | null>(null);
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // Sync theme with document element
  useEffect(() => {
    if (state.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state.isDarkMode]);

  // Auth Listener
  useEffect(() => {
    let isMounted = true;

    const unsubscribe = onAuthStateChanged(async (user) => {
      if (!isMounted) return;

      if (user) {
        setUserId(user.uid);
        const userData = await loadUserData(user.uid);

        if (userData) {
          setState(prev => ({
            ...prev,
            user: {
              name: user.displayName || 'User',
              avatar: user.photoURL || DEFAULT_AVATAR
            },
            monthlyAllowance: userData.monthlyAllowance || 0,
            transactions: userData.transactions || [],
            goals: userData.goals || [],
            currentScreen: (userData.monthlyAllowance > 0) ? 'dashboard' : 'setup'
          }));
        } else {
          setState(prev => ({
            ...prev,
            user: {
              name: user.displayName || 'User',
              avatar: user.photoURL || DEFAULT_AVATAR
            },
            currentScreen: 'setup'
          }));
        }
      } else {
        setUserId(null);
        setState(prev => ({ 
          ...prev, 
          currentScreen: 'welcome', 
          monthlyAllowance: 0, 
          transactions: [], 
          goals: [] 
        }));
      }
      setLoading(false);
    });

    return () => { isMounted = false; unsubscribe(); };
  }, []);

  const persistData = async (updates: Partial<AppState>) => {
    if (!userId) return;
    await saveUserData(userId, updates);
  };

  const updateScreen = (screen: AppState['currentScreen']) => {
    setState(prev => ({ ...prev, currentScreen: screen }));
  };

  const handleDashboardAction = (screen: AppState['currentScreen'], query?: string) => {
    if (query) setPendingChatQuery(query);
    updateScreen(screen);
  };

  const handleAddTransaction = (tx: Transaction) => {
    const updatedTxs = [tx, ...state.transactions];
    setState(prev => ({ ...prev, transactions: updatedTxs }));
    persistData({ transactions: updatedTxs });
  };

  const handleAddGoal = (goal: Goal) => {
    const updatedGoals = [...state.goals, goal];
    setState(prev => ({ ...prev, goals: updatedGoals, currentScreen: 'dashboard' }));
    persistData({ goals: updatedGoals });
  };

  const handleUpdateGoal = (goalId: string, savedAmount: number) => {
    const updatedGoals = state.goals.map(g => g.id === goalId ? { ...g, savedAmount: g.savedAmount + savedAmount } : g);
    setState(prev => ({ ...prev, goals: updatedGoals }));
    persistData({ goals: updatedGoals });
  };

  const handleDeleteGoal = (goalId: string) => {
    const updatedGoals = state.goals.filter(g => g.id !== goalId);
    setState(prev => ({ ...prev, goals: updatedGoals }));
    persistData({ goals: updatedGoals });
  };

  const setAllowance = (amount: number) => {
    setState(prev => ({ ...prev, monthlyAllowance: amount, currentScreen: 'dashboard' }));
    persistData({ monthlyAllowance: amount });
  };

  const handleLogout = async () => {
    await signOut();
    updateScreen('welcome');
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-[#050505]">
        <div className="relative size-20">
          <div className="absolute inset-0 border-4 border-primary/20 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-t-primary rounded-full animate-spin"></div>
        </div>
      </div>
    );
  }

  const renderScreen = () => {
    switch (state.currentScreen) {
      case 'welcome':
        return <WelcomeScreen language={state.language} onToggleLang={() => setState(p => ({...p, language: p.language === 'ENG' ? 'HIN' : 'ENG'}))} onContinue={() => {}} />;
      case 'setup':
        return <SetupScreen state={state} onSave={setAllowance} />;
      case 'dashboard':
        return <DashboardScreen state={state} onAction={handleDashboardAction} onUpdateGoal={handleUpdateGoal} onDeleteGoal={handleDeleteGoal} />;
      case 'analytics':
        return <AnalyticsScreen state={state} onBack={() => updateScreen('dashboard')} onAction={handleDashboardAction} />;
      case 'tools':
        return <ToolsScreen state={state} onBack={() => updateScreen('dashboard')} onAddGoal={handleAddGoal} />;
      case 'chat':
        return <ChatScreen state={state} onBack={() => updateScreen('dashboard')} initialQuery={pendingChatQuery} onClearInitialQuery={() => setPendingChatQuery(null)} />;
      case 'offers':
        return <OffersScreen state={state} onBack={() => updateScreen('dashboard')} onNavigate={updateScreen} />;
      case 'scan':
        return <ScanResultScreen state={state} scannedImage={scannedImage} onBack={() => updateScreen('dashboard')} onAddTransaction={handleAddTransaction} />;
      case 'manual_entry':
        return <ManualEntryScreen state={state} onBack={() => updateScreen('dashboard')} onAddTransaction={handleAddTransaction} />;
      case 'settings':
        return (
          <SettingsScreen 
            state={state} 
            onBack={() => updateScreen('dashboard')} 
            onLogout={handleLogout} 
            onToggleLang={() => setState(p => ({...p, language: p.language === 'ENG' ? 'HIN' : 'ENG'}))} 
            onToggleTheme={() => setState(p => ({...p, isDarkMode: !p.isDarkMode}))}
          />
        );
      default:
        return <DashboardScreen state={state} onAction={handleDashboardAction} onUpdateGoal={handleUpdateGoal} onDeleteGoal={handleDeleteGoal} />;
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-background-light dark:bg-[#050505] transition-colors duration-300">
      <div className="w-full max-w-md relative flex flex-col bg-background-light dark:bg-background-dark shadow-2xl overflow-hidden min-h-screen">
        {state.currentScreen === 'scan' && !scannedImage ? (
           <ScanScreen onBack={() => updateScreen('dashboard')} onCapture={(img) => { setScannedImage(img); updateScreen('scan'); }} />
        ) : (
          renderScreen()
        )}

        {['dashboard', 'analytics', 'tools', 'chat', 'offers'].includes(state.currentScreen) && (
          <Navigation currentScreen={state.currentScreen} onNavigate={(screen) => {
            if (screen === 'scan') setScannedImage(null);
            updateScreen(screen);
          }} />
        )}
      </div>
    </div>
  );
};

export default App;

import { initializeApp, getApps } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js";
import { getAuth, GoogleAuthProvider, signInWithPopup as firebaseSignIn, signOut as firebaseSignOut, onAuthStateChanged as firebaseOnAuth } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-auth.js";
import { getFirestore, doc, setDoc, getDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

// detect if we have a valid-looking Firebase Key
const isFirebaseKey = (key: any) => typeof key === 'string' && key.startsWith('AIza');

const firebaseConfig = {
  apiKey: isFirebaseKey(process.env.API_KEY) ? process.env.API_KEY : "AIzaSyPlaceholder",
  authDomain: "wiseup-ai.firebaseapp.com",
  projectId: "wiseup-ai",
  storageBucket: "wiseup-ai.appspot.com",
  messagingSenderId: "10987654321",
  appId: "1:10987654321:web:a1b2c3d4e5f6"
};

let app: any;
let auth: any;
let db: any;
let isRealFirebase = false;

try {
  if (isFirebaseKey(process.env.API_KEY)) {
    app = !getApps().length ? initializeApp(firebaseConfig) : getApps()[0];
    auth = getAuth(app);
    db = getFirestore(app);
    isRealFirebase = true;
    console.log("Firebase initialized successfully.");
  } else {
    throw new Error("No valid Firebase key found, switching to Local Mode.");
  }
} catch (e) {
  console.warn("Using Local Mode:", e);
  isRealFirebase = false;
  // Minimal shells for API compatibility
  auth = { currentUser: null };
  db = {};
}

const googleProvider = new GoogleAuthProvider();

// Hybrid Auth
export const signInWithGoogle = async () => {
  if (isRealFirebase) {
    try {
      return await firebaseSignIn(auth, googleProvider);
    } catch (e: any) {
      if (e.code === 'auth/api-key-not-valid' || e.code === 'auth/invalid-api-key') {
        return mockLogin();
      }
      throw e;
    }
  }
  return mockLogin();
};

const mockLogin = () => {
  const mockUser = {
    uid: "local-user-id",
    displayName: "Demo User",
    photoURL: "https://i.ibb.co/L5Vb7N5/thug-life-avatar.jpg",
    email: "demo@wiseup.ai"
  };
  localStorage.setItem('wiseup_mock_user', JSON.stringify(mockUser));
  window.dispatchEvent(new Event('auth-change'));
  return { user: mockUser };
};

export const signOut = async () => {
  if (isRealFirebase) await firebaseSignOut(auth);
  localStorage.removeItem('wiseup_mock_user');
  window.dispatchEvent(new Event('auth-change'));
};

export const onAuthStateChanged = (callback: (user: any) => void) => {
  if (isRealFirebase) {
    return firebaseOnAuth(auth, callback);
  } else {
    const checkLocal = () => {
      const stored = localStorage.getItem('wiseup_mock_user');
      callback(stored ? JSON.parse(stored) : null);
    };
    window.addEventListener('auth-change', checkLocal);
    checkLocal();
    return () => window.removeEventListener('auth-change', checkLocal);
  }
};

// Hybrid Data Persistence
export const saveUserData = async (uid: string, data: any) => {
  if (isRealFirebase) {
    try {
      const userDocRef = doc(db, "users", uid);
      await setDoc(userDocRef, data, { merge: true });
    } catch (e) {
      console.warn("Firestore save failed, falling back to LocalStorage:", e);
      localStorage.setItem(`wiseup_data_${uid}`, JSON.stringify(data));
    }
  } else {
    localStorage.setItem(`wiseup_data_${uid}`, JSON.stringify(data));
  }
};

export const loadUserData = async (uid: string) => {
  if (isRealFirebase) {
    try {
      const userDocRef = doc(db, "users", uid);
      const userDoc = await getDoc(userDocRef);
      if (userDoc.exists()) return userDoc.data();
    } catch (e) {
      console.warn("Firestore load failed, checking LocalStorage:", e);
    }
  }
  const localData = localStorage.getItem(`wiseup_data_${uid}`);
  return localData ? JSON.parse(localData) : null;
};

