/**
 * Robust hybrid listener for both Real and Mock auth states
 */
export const onAuthStateChanged = (callback: (user: any) => void) => {
  const checkCurrentState = (firebaseUser: any = null) => {
    // Priority 1: Check if a mock user session exists in local storage
    const stored = localStorage.getItem('wiseup_mock_user');
    if (stored) {
      try {
        callback(JSON.parse(stored));
        return;
      } catch(e) {
        localStorage.removeItem('wiseup_mock_user');
      }
    }

    // Priority 2: Use the Firebase user if one was provided/detected
    if (firebaseUser) {
      callback(firebaseUser);
      return;
    }

    // Default: No one is logged in
    callback(null);
  };

  // Listen to custom local auth changes (for Demo mode)
  const handleLocalChange = () => checkCurrentState();
  window.addEventListener('auth-change', handleLocalChange);

  // Listen to real Firebase auth changes
  let unsubscribeFirebase: any = () => {};
  if (isRealFirebase && auth) {
    unsubscribeFirebase = firebaseOnAuth(auth, (user: any) => {
      checkCurrentState(user);
    });
  } else {
    // If no firebase, just do an initial check of local state
    checkCurrentState();
  }

  return () => {
    window.removeEventListener('auth-change', handleLocalChange);
    if (typeof unsubscribeFirebase === 'function') unsubscribeFirebase();
  };
};

