import React, { useState, useRef, useEffect } from 'react';
import { AppState } from '../types';

interface NavigationProps {
  currentScreen: AppState['currentScreen'];
  onNavigate: (screen: AppState['currentScreen']) => void;
}

const Navigation: React.FC<NavigationProps> = ({ currentScreen, onNavigate }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  const navItems: { screen: AppState['currentScreen']; label: string; icon: string }[] = [
    { screen: 'dashboard', label: 'Home', icon: 'home' },
    { screen: 'analytics', label: 'Stats', icon: 'analytics' },
    { screen: 'chat', label: 'Guru', icon: 'psychology' },
    { screen: 'offers', label: 'Offers', icon: 'local_offer' },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 flex flex-col items-center pointer-events-none">
      <div className="w-full max-w-md pointer-events-auto relative" ref={menuRef}>

        {/* Expanded Menu */}
        {isMenuOpen && (
          <div className="absolute -top-36 left-1/2 transform -translate-x-1/2 flex flex-col gap-3 animate-in fade-in slide-in-from-bottom-5 duration-300">
            <button 
              onClick={() => { onNavigate('manual_entry'); setIsMenuOpen(false); }}
              className="flex items-center gap-3 bg-[#1a1814] border border-white/10 px-5 py-3 rounded-2xl shadow-2xl transition-all active:scale-95"
            >
              <div className="size-8 rounded-lg bg-primary/20 flex items-center justify-center text-primary">
                <span className="material-symbols-outlined text-xl">edit_note</span>
              </div>
              <span className="text-white text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Add Manually</span>
            </button>
            <button 
              onClick={() => { onNavigate('scan'); setIsMenuOpen(false); }}
              className="flex items-center gap-3 bg-[#1a1814] border border-white/10 px-5 py-3 rounded-2xl shadow-2xl transition-all active:scale-95"
            >
              <div className="size-8 rounded-lg bg-primary/20 flex items-center justify-center text-primary">
                <span className="material-symbols-outlined text-xl">photo_camera</span>
              </div>
              <span className="text-white text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Scan Bill</span>
            </button>
          </div>
        )}

        <div className="relative pb-8 pt-3 px-6 flex items-center justify-between bg-[#0a0a0f]/95 backdrop-blur-2xl border-t border-white/5">
          {/* Main Action Button (Screenshot Match) */}
          <div className="absolute -top-10 left-1/2 transform -translate-x-1/2">
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className={`relative flex items-center justify-center size-16 rounded-full bg-[#D0BB95] text-[#1a1a1a] shadow-[0_0_30px_rgba(208,187,149,0.3)] transition-all active:scale-95 border-[3px] border-[#0a0a0f] ${isMenuOpen ? 'rotate-45' : ''}`}
            >
              <span className="material-symbols-outlined text-2xl font-black">receipt_long</span>
              <div className="absolute -inset-1 rounded-full border border-primary/20 animate-pulse"></div>
            </button>
          </div>

          {navItems.map((item, index) => {
            const isActive = currentScreen === item.screen;
            return (
              <React.Fragment key={item.screen}>
                {index === 2 && <div className="w-12" />}
                <button
                  onClick={() => { onNavigate(item.screen); setIsMenuOpen(false); }}
                  className={`flex flex-col items-center gap-1 w-12 transition-all ${isActive ? 'text-[#D0BB95]' : 'text-slate-600'}`}
                >
                  <span className={`material-symbols-outlined text-2xl ${isActive ? 'filled' : ''}`}>{item.icon}</span>
                  <span className={`text-[10px] tracking-tight uppercase font-black`}>{item.label}</span>
                </button>
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </div>
  );
};

