      completed: 'लक्षय पूरा हुआ!',
      roastPrompt: "मेरे हालिया खर्चों को रोस्ट करें। हिंग्लिश में और मजाकिया अंदाज में 4-6 लाइनों में जवाब दें।",
      praisePrompt: "गुरु, मेरा अनुशासन देखो! मेरा एक भी लापरवाह खर्च नहीं है। मुझे अपनी शैली में शाबाशी दें।",
      starterPrompt: "गुरु, अभी तक मेरा कोई खर्च नहीं है। एक नए खिलाड़ी के लिए आपकी क्या सलाह है?",
      roastSubtitle: 'गुरु को अपने बटुए का न्याय करने दें',
      praiseSubtitle: 'गुरु आपसे प्रभावित हैं',
      starterSubtitle: 'अपनी यात्रा शुरू करें'
    }
  }[state.language];

  const handleQuickAsk = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!quickAsk.trim()) return;
    onAction('chat', quickAsk);
    setQuickAsk('');
  };

  const handleGoalSave = (goalId: string) => {
    const amount = Number(goalSaveInputs[goalId]);
    if (isNaN(amount) || amount <= 0) return;
    onUpdateGoal(goalId, amount);
    setGoalSaveInputs(prev => ({ ...prev, [goalId]: '' }));
  };

  const roastStatus = totalSpent === 0 ? 'starter' : (impulsiveSpent === 0 ? 'praise' : 'roast');
  const roastLabel = roastStatus === 'starter' ? t.starter : (roastStatus === 'praise' ? t.praise : t.roast);
  const roastSubtitle = roastStatus === 'starter' ? t.starterSubtitle : (roastStatus === 'praise' ? t.praiseSubtitle : t.roastSubtitle);
  const roastIcon = roastStatus === 'starter' ? 'emoji_objects' : (roastStatus === 'praise' ? 'verified_user' : 'local_fire_department');
  const roastColor = roastStatus === 'starter' ? 'text-primary' : (roastStatus === 'praise' ? 'text-wise' : 'text-red-500');
  const roastBg = roastStatus === 'starter' ? 'bg-primary/10' : (roastStatus === 'praise' ? 'bg-wise/10' : 'bg-red-500/10');
  const roastBorder = roastStatus === 'starter' ? 'border-primary/20' : (roastStatus === 'praise' ? 'border-wise/20' : 'border-red-500/20');

  const triggerRoastAction = () => {
    const prompt = roastStatus === 'starter' ? t.starterPrompt : (roastStatus === 'praise' ? t.praisePrompt : t.roastPrompt);
    onAction('chat', prompt);
  };

  return (
    <div className="flex-1 flex flex-col p-5 pb-32 overflow-y-auto no-scrollbar relative bg-[#050505] transition-colors">
      <div className="fixed inset-0 z-0 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-primary/5 via-transparent to-transparent opacity-50"></div>

      <header className="relative z-10 flex items-center justify-between pt-4 mb-8">
        <div className="flex items-center gap-4">
          <div className="relative group cursor-pointer" onClick={() => onAction('settings')}>
            <div className="size-12 rounded-full bg-white flex items-center justify-center overflow-hidden border border-white/10 ring-2 ring-white/5">
              {state.user.avatar ? (
                <img src={state.user.avatar} className="size-full object-cover" alt="Profile" />
              ) : (
                <span className="material-symbols-outlined text-slate-400">person</span>
              )}
            </div>
            <div className="absolute bottom-0 right-0 size-3 bg-green-500 rounded-full border-2 border-[#050505]"></div>
          </div>
          <div>
            <p className="text-primary/50 text-[10px] font-black uppercase tracking-[0.2em] mb-0.5">{t.morning}</p>
            <h1 className="text-white text-xl font-black tracking-tight">{t.welcome}</h1>
          </div>
        </div>
        <button onClick={() => onAction('settings')} className="flex items-center justify-center rounded-full size-11 bg-white/5 border border-white/5 hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined text-slate-400 text-2xl">tune</span>
        </button>
      </header>

      <main className="relative z-10 space-y-8">
        <section className="bg-[#121110] rounded-[2.5rem] p-7 border border-white/5 shadow-2xl space-y-6">
          <div className="flex gap-4 items-start">
            <div className="size-12 rounded-2xl bg-[#D0BB95]/10 flex items-center justify-center border border-[#D0BB95]/20 shrink-0">
              <span className="material-symbols-outlined text-3xl text-primary font-light">psychology</span>
            </div>
            <div className="flex-1 min-h-[48px] flex items-center">
              <p className="text-slate-200 text-sm font-medium leading-relaxed italic">
                {roastStatus === 'praise' ? "Guru is impressed with your discipline. Keep it up!" : (roastStatus === 'starter' ? "Ready to build your empire? Start tracking now." : "Bhai, your wallet is crying. Let's fix this.")}
              </p>
            </div>
          </div>

          <form onSubmit={handleQuickAsk} className="relative flex items-center gap-3 mt-4">
            <div className="relative flex-1">
              <input 
                type="text" 
                value={quickAsk}
                onChange={(e) => setQuickAsk(e.target.value)}
                placeholder={t.quickAsk}
                className="w-full bg-[#1c1b19] border border-white/5 rounded-2xl py-4 pl-5 pr-4 text-sm text-white focus:ring-1 focus:ring-primary/40 outline-none transition-all placeholder:text-slate-600 font-medium"
              />
            </div>
            <button 
              type="submit"
              className="size-12 flex items-center justify-center bg-primary text-background-dark rounded-2xl shadow-xl shadow-primary/20 active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined font-black">send</span>
            </button>
          </form>
        </section>

        <div className="flex items-center justify-between px-1">
          <h3 className="text-white text-lg font-black tracking-tight uppercase">{t.goals}</h3>
          <button 
            className="bg-primary text-background-dark px-6 py-2.5 rounded-full font-black text-[10px] uppercase tracking-widest shadow-xl shadow-primary/10 active:scale-95 transition-all" 
            onClick={() => onAction('tools')}
          >
            {t.planMore}
          </button>
        </div>

        <section className="grid grid-cols-2 gap-4">
          <div className="bg-[#121110] rounded-[2.5rem] p-7 border border-white/5 shadow-xl flex flex-col min-h-[170px] relative overflow-hidden">
            <div className="flex items-center gap-2.5 mb-8">
              <div className="size-2 rounded-full bg-wise shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
              <span className="text-slate-500 text-[10px] font-black uppercase tracking-[0.1em]">{t.wise}</span>
            </div>
            <p className="text-5xl font-black text-white tracking-tighter mb-auto">₹{wiseSpent.toLocaleString()}</p>
            <p className="text-[10px] text-wise font-black uppercase tracking-[0.2em]">{t.smartMoves}</p>
          </div>

          <div className="bg-[#121110] rounded-[2.5rem] p-7 border border-white/5 shadow-xl flex flex-col min-h-[170px] relative overflow-hidden">
            <div className="flex items-center gap-2.5 mb-8">
              <div className="size-2 rounded-full bg-impulsive shadow-[0_0_8px_rgba(255,82,82,0.5)]"></div>
              <span className="text-slate-500 text-[10px] font-black uppercase tracking-[0.1em]">{t.impulsive}</span>
            </div>
            <p className="text-5xl font-black text-white tracking-tighter mb-auto">₹{impulsiveSpent.toLocaleString()}</p>
            <div className="flex flex-col gap-1">
              <p className="text-[10px] text-impulsive font-black uppercase tracking-[0.2em]">{t.guruWatching}</p>
              <span className="text-xs">💸 😜</span>
            </div>
          </div>
        </section>

        <section>
          <button 
            onClick={triggerRoastAction}
            className="w-full bg-[#121110] rounded-[2.5rem] p-7 border border-white/5 group hover:border-white/20 transition-all active:scale-[0.98] shadow-2xl relative overflow-hidden"
          >
            <div className={`absolute -right-20 -top-20 size-64 blur-[100px] pointer-events-none opacity-10 ${roastStatus === 'praise' ? 'bg-wise' : (roastStatus === 'starter' ? 'bg-primary' : 'bg-red-500')}`}></div>

            <div className="flex items-center justify-between relative z-10">
              <div className="flex items-center gap-5">
                <div className={`size-14 rounded-2xl ${roastBg} flex items-center justify-center border ${roastBorder} group-hover:scale-105 transition-transform`}>
                  <span className={`material-symbols-outlined ${roastColor} text-3xl filled`}>{roastIcon}</span>
                </div>
                <div className="text-left">
                  <h3 className="text-white font-black text-base uppercase tracking-tight mb-0.5">
                    {roastLabel}
                  </h3>
                  <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest">{roastSubtitle}</p>
                </div>
              </div>
              <span className="material-symbols-outlined text-slate-600 group-hover:translate-x-1 transition-transform">chevron_right</span>
            </div>
          </button>
        </section>

        {state.goals.length > 0 && (
           <section className="space-y-4 pt-2">
            <div className="flex items-center justify-between px-1">
              <h3 className="text-white text-sm font-black uppercase tracking-widest">{t.activeGoals}</h3>
            </div>
            <div className="space-y-4">
              {state.goals.map(goal => {
                const progress = Math.min((goal.savedAmount / goal.targetAmount) * 100, 100);
                const isCompleted = progress >= 100;
                return (
                  <div key={goal.id} className="bg-[#121110] rounded-[2rem] p-6 border border-white/5 shadow-xl space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="size-11 rounded-xl bg-primary/10 flex items-center justify-center border border-primary/20">
                          <span className="material-symbols-outlined text-primary">{goal.icon}</span>
                        </div>
                        <div>
                          <h4 className="text-white text-base font-black tracking-tight uppercase">{goal.name}</h4>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">
                            ₹{goal.savedAmount.toLocaleString()} / ₹{goal.targetAmount.toLocaleString()}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {!isCompleted && (
                          <>
                            <input 
                              type="number"
                              placeholder="₹"
                              value={goalSaveInputs[goal.id] || ''}
                              onChange={(e) => setGoalSaveInputs(prev => ({ ...prev, [goal.id]: e.target.value }))}
                              className="w-16 h-9 bg-[#1c1b19] border border-white/5 rounded-lg text-xs text-white px-2.5 focus:ring-1 focus:ring-primary/40 outline-none"
                            />
                            <button 
                              onClick={() => handleGoalSave(goal.id)}
                              className="bg-primary text-background-dark text-[10px] font-black uppercase px-3 h-9 rounded-lg shadow-lg shadow-primary/10 active:scale-95 transition-all"
                            >
                              Add
                            </button>
                          </>
                        )}
                        <button 
                          onClick={() => onDeleteGoal(goal.id)}
                          className="size-9 rounded-full bg-white/5 text-slate-500 flex items-center justify-center hover:bg-red-500 transition-all hover:text-white"
                        >
                          <span className="material-symbols-outlined text-sm">delete</span>
                        </button>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                        <span className={isCompleted ? "text-wise" : "text-slate-500"}>
                          {isCompleted ? t.completed : `${Math.round(progress)}%`}
                        </span>
                        <span className="text-slate-600">₹{(goal.targetAmount - goal.savedAmount > 0 ? goal.targetAmount - goal.savedAmount : 0).toLocaleString()} LEFT</span>
                      </div>
                      <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden">
                        <div className={`h-full transition-all duration-1000 ${isCompleted ? 'bg-wise' : 'bg-primary'}`} style={{ width: `${progress}%` }}></div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </section>
        )}

        <footer className="flex flex-col items-center justify-center gap-1 mt-12 mb-4 opacity-30">
          <p className="text-slate-600 text-[10px] font-bold uppercase tracking-widest">
            Created by the Perpetual Motion Squad
          </p>
          <p className="text-slate-600 text-[10px] font-bold uppercase tracking-[0.2em]">
            &lt;Jay Sonar&gt;
          </p>
        </footer>
      </main>
    </div>
  );
};

export default DashboardScreen;
